from __future__ import annotations

from typing import Any

from alembic import context
from balise_api.config import get_settings
from balise_api.models import Base
from sqlalchemy import create_engine, pool

config = context.config
target_metadata = Base.metadata

_SKIPPED_TABLES = {"spatial_ref_sys", "geography_columns", "geometry_columns"}


def include_object(
    obj: Any, name: str | None, type_: str, reflected: bool, compare_to: Any
) -> bool:
    """PostGIS system tables must never end up in an autogenerated migration (docs/11)."""
    if type_ == "table" and name in _SKIPPED_TABLES:
        return False
    return not (type_ == "index" and name is not None and name.startswith("idx_"))


def run_migrations_offline() -> None:
    context.configure(
        url=get_settings().sync_database_url,
        target_metadata=target_metadata,
        literal_binds=True,
        include_object=include_object,
        compare_type=True,
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    # The postgis image enables tiger_geocoder and topology and adds their schemas to the database
    # search_path; reflecting them would make `alembic check` report ~36 phantom tables to drop. We
    # only ever own public. Set on connect, not with a statement: a statement would open a
    # transaction, and alembic would then skip its own — silently rolling every migration back.
    engine = create_engine(
        get_settings().sync_database_url,
        poolclass=pool.NullPool,
        connect_args={"options": "-c search_path=public"},
    )
    with engine.connect() as connection:
        context.configure(
            connection=connection,
            target_metadata=target_metadata,
            include_object=include_object,
            compare_type=True,
        )
        with context.begin_transaction():
            context.run_migrations()
    engine.dispose()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
